import { useParams } from "react-router-dom";
import { useEffect, useState } from "react";

import "./Product.css";

function Product() {
  const { id } = useParams();
  const [prod, setProd] = useState([]);
  useEffect(() => {
    fetch("https://dummyjson.com/products")
      .then((res) => res.json())
      .then((res) => setProd(res.products));
  }, []);

  const productData = prod.filter((elm) => elm.id === Number(id));

  console.log(productData);

  return (
    <div>
      {productData.map((elm) => {
        return (
          <div key={elm.id}>
            <img src={elm.images} alt="" />
            <div className="description">
              <h2>{elm.title}</h2>
              <p>{elm.description}</p>
              <p>Brand: {elm.brand}</p>
              <h3>Category: {elm.category}</h3>
              <p>Availability: {elm.availabilityStatus}</p>
              <p>In stock: {elm.stock}</p>
              <p>Warranty: {elm.warrantyInform}</p>
              <p>Returning policy: {elm.returnPolicy}</p>
              <p>Shipping: {elm.Number}</p>
            </div>
          </div>
        );
      })}

      {/* <img src={productData.id} alt="product" /> */}
      {/* <div className="discription">
    <h2>{productData.title}</h2>
    <h3>Category: {productData.category}</h3>
</div> */}
    </div>
  );
}

export default Product;
